@PluginDescriptor(
	name = "BIS Loadouts",
	description = "Side-panel boss gear analyzer that recommends best wearable OSRS gear by stats, boss, and combat style.",
	tags = {"boss", "pvm", "loadout", "gear", "bis"}
)
@Slf4j
public class BisLoadoutsPlugin extends Plugin
{
	private static final int MAX_SCORE = 100;

	@Inject
	private Client client;

	@Inject
	private BisLoadoutsConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OkHttpClient okHttpClient;

	private BossDataService bossDataService;
	private ExecutorService apiExecutor;
	private BisLoadoutsPanel panel;
	private NavigationButton navButton;
	private volatile String selectedBossName = "None";
	private volatile CombatStyle selectedStyle = CombatStyle.AUTO;

	@Override
	protected void startUp()
	{
		log.debug("BIS Loadouts started");
		bossDataService = new BossDataService(okHttpClient);
		apiExecutor = Executors.newSingleThreadExecutor();
		panel = new BisLoadoutsPanel();
		panel.setItemIconProvider(this::applyItemIcon);
		panel.setItemWikiOpener(this::openItemWiki);
		panel.setAnalyzeListener((bossName, style) -> {
			selectedBossName = bossName;
			selectedStyle = style == null ? CombatStyle.AUTO : style;
			refreshPanel(true);
		});
		panel.showWaitingForLogin(bossDataService.getBossNameSuggestions(1000), bossDataService.getStatus());
		navButton = NavigationButton.builder()
			.tooltip("BIS Loadouts")
			.icon(createIcon())
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		apiExecutor.submit(() -> {
			try
			{
				bossDataService.refresh();
			}
			catch (Exception ex)
			{
				log.warn("Unable to refresh OSRS Wiki/GearScape data", ex);
			}
			refreshPanel(false);
		});
	}

	@Override
	protected void shutDown()
	{
		log.debug("BIS Loadouts stopped");
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		if (apiExecutor != null)
		{
			apiExecutor.shutdownNow();
		}
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() == GameState.LOGGED_IN)
		{
			refreshPanel(false);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("bisloadouts".equals(event.getGroup()))
		{
			refreshPanel(false);
		}
	}

	static int calculateLoadoutScore(int combatLevel, int hitpointsLevel, int prayerLevel, int defenceLevel,
		int targetCombatLevel, int targetPrayerLevel)
	{
		int safeTargetCombat = Math.max(1, targetCombatLevel);
		int safeTargetPrayer = Math.max(1, targetPrayerLevel);

		double combatScore = ratioScore(combatLevel, safeTargetCombat) * 0.55D;
		double hitpointsScore = ratioScore(hitpointsLevel, 99) * 0.20D;
		double prayerScore = ratioScore(prayerLevel, safeTargetPrayer) * 0.15D;
		double defenceScore = ratioScore(defenceLevel, 99) * 0.10D;

		return clampScore((int) Math.round(combatScore + hitpointsScore + prayerScore + defenceScore));
	}

	private static double ratioScore(int actual, int target)
	{
		return Math.min(1.0D, Math.max(0.0D, actual / (double) target)) * MAX_SCORE;
	}

	private static int clampScore(int score)
	{
		return Math.max(0, Math.min(MAX_SCORE, score));
	}

	private void refreshPanel(boolean forceAnalyze)
	{
		if (panel == null)
		{
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			SwingUtilities.invokeLater(() -> {
				if (panel != null)
				{
					panel.showWaitingForLogin(bossDataService.getBossNameSuggestions(1000), bossDataService.getStatus());
				}
			});
			return;
		}
		PlayerStats stats = new PlayerStats(
			client.getRealSkillLevel(Skill.ATTACK),
			client.getRealSkillLevel(Skill.STRENGTH),
			client.getRealSkillLevel(Skill.DEFENCE),
			client.getRealSkillLevel(Skill.HITPOINTS),
			client.getRealSkillLevel(Skill.MAGIC),
			client.getRealSkillLevel(Skill.RANGED),
			client.getRealSkillLevel(Skill.PRAYER)
		);
		String requestedBossName = selectedBossName;
		CombatStyle style = selectedStyle;
		BudgetTier budget = config.budgetTier();
		apiExecutor.submit(() -> {
			BossTarget target = bossDataService.resolveBoss(requestedBossName, BossProfile.GENERAL_PVM);
			SetupRecommendation recommendation = forceAnalyze || panel != null
				? GearRecommendationEngine.recommend(target, style, budget, stats, bossDataService.getGearItems())
				: null;
			String status = bossDataService.getStatus();
			SwingUtilities.invokeLater(() -> {
				if (panel != null)
				{
					panel.updateRecommendation(recommendation, target, status, bossDataService.getBossNameSuggestions(1000));
				}
			});
		});
	}

	private void openItemWiki(GearItem item)
	{
		if (item == null || item.getWikiUrl() == null || item.getWikiUrl().isEmpty())
		{
			return;
		}
		LinkBrowser.browse(item.getWikiUrl());
	}

	private void applyItemIcon(GearItem item, JLabel label)
	{
		if (item == null)
		{
			return;
		}
		if (item.getIconBase64() != null && !item.getIconBase64().isEmpty())
		{
			try
			{
				BufferedImage image = ImageIO.read(new ByteArrayInputStream(Base64.getDecoder().decode(item.getIconBase64())));
				if (image != null)
				{
					Image scaled = image.getScaledInstance(32, 32, Image.SCALE_FAST);
					label.setIcon(new ImageIcon(scaled));
					return;
				}
			}
			catch (IOException | IllegalArgumentException ex)
			{
				log.debug("Unable to decode embedded item icon for {}", item.getName(), ex);
			}
		}
		if (item.getItemId() <= 0)
		{
			return;
		}
		try
		{
			AsyncBufferedImage image = itemManager.getImage(item.getItemId());
			image.addTo(label);
		}
		catch (Exception ex)
		{
			log.debug("Unable to load item image for {} ({})", item.getName(), item.getItemId(), ex);
		}
	}

	private static BufferedImage createIcon()
	{
		try (InputStream stream = BisLoadoutsPlugin.class.getResourceAsStream("bis_loadouts_icon.png"))
		{
			if (stream != null)
			{
				return ImageIO.read(stream);
			}
		}
		catch (IOException ignored)
		{
			// Fall through to a generated fallback so the toolbar never breaks.
		}

		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setColor(new Color(33, 150, 243));
		graphics.fillOval(1, 1, 14, 14);
		graphics.setColor(Color.WHITE);
		graphics.drawString("B", 4, 12);
		graphics.dispose();
		return image;
	}

	@Provides
	BisLoadoutsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BisLoadoutsConfig.class);
	}
}

