public class GearItem
{
	private final GearSlot slot;
	private final int itemId;
	private final String name;
	private final Set<CombatStyle> styles;
	private final int attackReq;
	private final int strengthReq;
	private final int defenceReq;
	private final int magicReq;
	private final int rangedReq;
	private final int prayerReq;
	private final int attackBonus;
	private final int strengthBonus;
	private final long price;
	private final String note;
	private final String iconBase64;
	private final String wikiUrl;
	private final boolean twoHanded;
	private final Set<Integer> compatibleAmmoIds;

	public GearItem(GearSlot slot, String name, Set<CombatStyle> styles, int attackReq, int strengthReq, int defenceReq,
		int magicReq, int rangedReq, int prayerReq, int attackBonus, int strengthBonus, long price, String note)
	{
		this(slot, -1, name, styles, attackReq, strengthReq, defenceReq, magicReq, rangedReq, prayerReq, attackBonus, strengthBonus, price, note);
	}

	public GearItem(GearSlot slot, int itemId, String name, Set<CombatStyle> styles, int attackReq, int strengthReq, int defenceReq,
		int magicReq, int rangedReq, int prayerReq, int attackBonus, int strengthBonus, long price, String note)
	{
		this(slot, itemId, name, styles, attackReq, strengthReq, defenceReq, magicReq, rangedReq, prayerReq, attackBonus, strengthBonus, price, note, null);
	}

	public GearItem(GearSlot slot, int itemId, String name, Set<CombatStyle> styles, int attackReq, int strengthReq, int defenceReq,
		int magicReq, int rangedReq, int prayerReq, int attackBonus, int strengthBonus, long price, String note, String iconBase64)
	{
		this(slot, itemId, name, styles, attackReq, strengthReq, defenceReq, magicReq, rangedReq, prayerReq, attackBonus, strengthBonus, price, note, iconBase64, OsrsWikiApiClient.pageUrl(name));
	}

	public GearItem(GearSlot slot, int itemId, String name, Set<CombatStyle> styles, int attackReq, int strengthReq, int defenceReq,
		int magicReq, int rangedReq, int prayerReq, int attackBonus, int strengthBonus, long price, String note, String iconBase64, String wikiUrl)
	{
		this(slot, itemId, name, styles, attackReq, strengthReq, defenceReq, magicReq, rangedReq, prayerReq, attackBonus, strengthBonus, price, note, iconBase64, wikiUrl, isKnownTwoHanded(slot, name));
	}

	public GearItem(GearSlot slot, int itemId, String name, Set<CombatStyle> styles, int attackReq, int strengthReq, int defenceReq,
		int magicReq, int rangedReq, int prayerReq, int attackBonus, int strengthBonus, long price, String note, String iconBase64, String wikiUrl, boolean twoHanded)
	{
		this(slot, itemId, name, styles, attackReq, strengthReq, defenceReq, magicReq, rangedReq, prayerReq, attackBonus, strengthBonus, price, note, iconBase64, wikiUrl, twoHanded, Collections.emptySet());
	}

	public GearItem(GearSlot slot, int itemId, String name, Set<CombatStyle> styles, int attackReq, int strengthReq, int defenceReq,
		int magicReq, int rangedReq, int prayerReq, int attackBonus, int strengthBonus, long price, String note, String iconBase64, String wikiUrl, boolean twoHanded, Set<Integer> compatibleAmmoIds)
	{
		this.slot = slot;
		this.itemId = itemId;
		this.name = name;
		this.styles = EnumSet.copyOf(styles);
		this.attackReq = attackReq;
		this.strengthReq = strengthReq;
		this.defenceReq = defenceReq;
		this.magicReq = magicReq;
		this.rangedReq = rangedReq;
		this.prayerReq = prayerReq;
		this.attackBonus = attackBonus;
		this.strengthBonus = strengthBonus;
		this.price = price;
		this.note = note;
		this.iconBase64 = iconBase64;
		this.wikiUrl = wikiUrl == null || wikiUrl.trim().isEmpty() ? OsrsWikiApiClient.pageUrl(name) : wikiUrl;
		this.twoHanded = twoHanded;
		this.compatibleAmmoIds = compatibleAmmoIds == null ? Collections.emptySet() : Collections.unmodifiableSet(new HashSet<>(compatibleAmmoIds));
	}

	public GearSlot getSlot()
	{
		return slot;
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getName()
	{
		return name;
	}

	public Set<CombatStyle> getStyles()
	{
		return styles;
	}

	public int getAttackReq()
	{
		return attackReq;
	}

	public int getStrengthReq()
	{
		return strengthReq;
	}

	public int getDefenceReq()
	{
		return defenceReq;
	}

	public int getMagicReq()
	{
		return magicReq;
	}

	public int getRangedReq()
	{
		return rangedReq;
	}

	public int getPrayerReq()
	{
		return prayerReq;
	}

	public int getAttackBonus()
	{
		return attackBonus;
	}

	public int getStrengthBonus()
	{
		return strengthBonus;
	}

	public long getPrice()
	{
		return price;
	}

	public String getNote()
	{
		return note;
	}

	public String getIconBase64()
	{
		return iconBase64;
	}

	public String getWikiUrl()
	{
		return wikiUrl;
	}

	public boolean isTwoHanded()
	{
		return twoHanded;
	}

	public boolean isOneHanded()
	{
		return slot == GearSlot.WEAPON && !twoHanded;
	}

	public Set<Integer> getCompatibleAmmoIds()
	{
		return compatibleAmmoIds;
	}

	public boolean acceptsAmmo(GearItem ammo)
	{
		if (ammo == null)
		{
			return false;
		}
		if (!compatibleAmmoIds.isEmpty())
		{
			return compatibleAmmoIds.contains(ammo.getItemId());
		}
		String weaponName = name == null ? "" : name.toLowerCase(java.util.Locale.ROOT);
		String ammoName = ammo.getName() == null ? "" : ammo.getName().toLowerCase(java.util.Locale.ROOT);
		if (isSelfContainedRangedWeapon(weaponName))
		{
			return false;
		}
		if (weaponName.contains("crossbow"))
		{
			return ammoName.contains("bolt") || ammoName.equals("bolt rack");
		}
		if (weaponName.contains("blowpipe"))
		{
			return ammoName.contains("dart");
		}
		if ((weaponName.contains(" bow") || weaponName.endsWith("bow")) && !weaponName.contains("crossbow"))
		{
			return ammoName.contains("arrow");
		}
		return true;
	}

	private static boolean isSelfContainedRangedWeapon(String weaponName)
	{
		return weaponName.contains("bow of faerdhinen")
			|| weaponName.contains("crystal bow")
			|| weaponName.contains("webweaver bow")
			|| weaponName.contains("craw's bow");
	}

	static boolean isKnownTwoHanded(GearSlot slot, String name)
	{
		if (slot != GearSlot.WEAPON || name == null)
		{
			return false;
		}
		String normalized = name.toLowerCase(java.util.Locale.ROOT);
		return normalized.contains("tumeken's shadow")
			|| normalized.contains("twisted bow")
			|| normalized.contains("bow of faerdhinen")
			|| normalized.contains("toxic blowpipe")
			|| normalized.contains("scorching bow")
			|| normalized.contains("noxious halberd")
			|| normalized.contains("soulreaper axe")
			|| normalized.contains("scythe")
			|| normalized.contains("halberd")
			|| normalized.contains("godsword")
			|| normalized.contains("maul")
			|| normalized.contains("greataxe")
			|| normalized.contains("2h sword")
			|| normalized.contains("colossal blade")
			|| normalized.contains("barrelchest anchor")
			|| normalized.contains("spear")
			|| normalized.contains("longbow")
			|| normalized.contains("shortbow")
			|| ((normalized.endsWith(" bow") || normalized.endsWith("bow")) && !normalized.contains("crossbow"));
	}

	public boolean supports(CombatStyle style)
	{
		if (style == CombatStyle.MELEE)
		{
			return styles.contains(CombatStyle.STAB) || styles.contains(CombatStyle.SLASH) || styles.contains(CombatStyle.CRUSH);
		}
		return styles.contains(style);
	}

	public boolean meetsRequirements(PlayerStats stats)
	{
		return stats.getAttack() >= attackReq
			&& stats.getStrength() >= strengthReq
			&& stats.getDefence() >= defenceReq
			&& stats.getMagic() >= magicReq
			&& stats.getRanged() >= rangedReq
			&& stats.getPrayer() >= prayerReq;
	}

	public int scoreValue()
	{
		return attackBonus + strengthBonus * 2;
	}
}

package com.itmeansbigmountain.bisloadouts;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

public final class GearRecommendationEngine
{
	private static final List<GearItem> ITEMS = buildItems();

	private GearRecommendationEngine()
	{
	}

	public static SetupRecommendation recommend(BossProfile boss, CombatStyle requestedStyle, BudgetTier budget, PlayerStats stats)
	{
		return recommend(BossTarget.fromProfile(boss), requestedStyle, budget, stats, ITEMS);
	}

	public static SetupRecommendation recommend(BossTarget boss, CombatStyle requestedStyle, BudgetTier budget, PlayerStats stats, List<GearItem> liveItems)
	{
		List<GearItem> candidateItems = mergeCandidateItems(liveItems);
		List<CombatStyle> styles = requestedStyle == CombatStyle.AUTO
			? Arrays.asList(CombatStyle.MAGIC, CombatStyle.RANGED, CombatStyle.MELEE)
			: Collections.singletonList(requestedStyle);

		List<SetupRecommendation> scored = styles.stream()
			.map(style -> recommendSingleStyle(boss, style, budget, stats, candidateItems))
			.sorted(Comparator.comparingDouble(SetupRecommendation::getEstimatedDps).reversed())
			.collect(Collectors.toList());

		SetupRecommendation best = scored.get(0);
		List<SetupRecommendation> alternatives = scored.stream()
			.filter(rec -> rec != best)
			.collect(Collectors.toList());

		return new SetupRecommendation(best.getBossName(), best.getStyle(), best.getItems(), best.getSlotAlternatives(), best.getEstimatedDps(),
			best.getHitChance(), best.getMaxHit(), best.getLoadoutScore(), best.getWarnings(), alternatives);
	}

	private static List<GearItem> mergeCandidateItems(List<GearItem> liveItems)
	{
		if (liveItems == null || liveItems.isEmpty())
		{
			return ITEMS;
		}
		Map<String, GearItem> merged = new LinkedHashMap<>();
		for (GearItem item : liveItems)
		{
			if (item != null && !isExcludedGameModeItem(item.getName()))
			{
				merged.put(item.getSlot() + ":" + item.getName().toLowerCase(Locale.ROOT), item);
			}
		}
		for (GearItem item : ITEMS)
		{
			if (!isExcludedGameModeItem(item.getName()))
			{
				// Local OSRS-backed items are curated to include current 2H megarares and to avoid
				// stale/mis-scored live API rows, so they intentionally override same-name live rows.
				merged.put(item.getSlot() + ":" + item.getName().toLowerCase(Locale.ROOT), item);
			}
		}
		return new ArrayList<>(merged.values());
	}

	static boolean isExcludedGameModeItem(String name)
	{
		if (name == null)
		{
			return false;
		}
		String normalized = name.toLowerCase(Locale.ROOT);
		return normalized.contains("(bh)")
			|| normalized.contains("(dmm)")
			|| normalized.contains("bounty hunter")
			|| normalized.contains("fractured archive")
			|| normalized.contains("dogsword")
			|| normalized.contains("thunder khopesh")
			|| normalized.contains("vesta's")
			|| normalized.contains("statius's")
			|| normalized.contains("morrigan's")
			|| normalized.contains("zuriel's")
			|| normalized.startsWith("corrupted ")
			|| normalized.startsWith("attuned ")
			|| normalized.startsWith("perfected ")
			|| normalized.startsWith("basic bow")
			|| normalized.startsWith("basic staff")
			|| normalized.startsWith("basic halberd")
			|| normalized.contains("(perfected)")
			|| normalized.contains("(attuned)")
			|| normalized.contains("(basic)")
			|| normalized.contains("deadman")
			|| normalized.contains("deadman's")
