	private static SetupRecommendation recommendSingleStyle(BossTarget boss, CombatStyle style, BudgetTier budget, PlayerStats stats, List<GearItem> items)
	{
		Map<GearSlot, GearItem> selected = new EnumMap<>(GearSlot.class);
		Map<GearSlot, List<GearItem>> slotAlternatives = new EnumMap<>(GearSlot.class);
		List<String> warnings = new ArrayList<>();

		for (GearSlot slot : GearSlot.values())
		{
			List<GearItem> alternatives = items.stream()
				.filter(item -> item.getSlot() == slot)
				.filter(item -> item.supports(style))
				.filter(item -> item.getPrice() <= budget.getMaxItemPrice())
				.filter(item -> item.meetsRequirements(stats))
				.sorted(Comparator.comparingInt((GearItem item) -> itemScore(item, boss, style, stats)).reversed())
				.collect(Collectors.toList());
			if (!alternatives.isEmpty())
			{
				selected.put(slot, alternatives.get(0));
				slotAlternatives.put(slot, alternatives);
			}
		}

		GearItem weapon = selected.get(GearSlot.WEAPON);
		if (weapon != null)
		{
			filterAmmoForWeapon(selected, slotAlternatives, weapon);
		}
		if (weapon != null && weapon.isTwoHanded())
		{
			selected.remove(GearSlot.SHIELD);
		}

		addRequirementWarnings(style, stats, warnings);
		if (!selected.containsKey(GearSlot.WEAPON))
		{
			warnings.add("No usable " + style + " weapon found for your stats/budget.");
		}

		int gearScore = selected.values().stream().mapToInt(GearItem::scoreValue).sum();
		double styleLevel = styleLevel(style, stats);
		double targetPressure = targetPressure(boss, style);
		double hitChance = clamp(0.35D + (styleLevel / 140.0D) + (gearScore / 900.0D) - targetPressure, 0.05D, 0.98D);
		int maxHit = Math.max(1, (int) Math.round((styleDamageLevel(style, stats) / 8.0D) + selected.values().stream().mapToInt(GearItem::getStrengthBonus).sum() / 10.0D));
		double attackSpeed = style == CombatStyle.MAGIC ? 2.4D : style == CombatStyle.RANGED ? 3.0D : 3.6D;
		boolean usesElementalWeakness = style == CombatStyle.MAGIC && weapon != null && boss.hasElementalWeakness()
			&& ElementalSpellScaling.canCastElementalSpell(weapon.getName())
			&& ElementalSpellScaling.bestBaseMaxHit(boss.getElementalWeakness(), stats.getMagic()) > 0;
		if (style == CombatStyle.MAGIC && boss.hasNpcMagicLevel())
		{
			int accuracyBonusPercent = usesElementalWeakness
				? boss.getElementalWeaknessPercent() + elementalWeaponSpellBonus(weapon) : 0;
			hitChance = magicHitChance(selected, stats.getMagic(), boss, accuracyBonusPercent);
		}
		if (usesElementalWeakness)
		{
			String spell = ElementalSpellScaling.bestSpellName(boss.getElementalWeakness(), stats.getMagic());
			int baseMaxHit = ElementalSpellScaling.bestBaseMaxHit(boss.getElementalWeakness(), stats.getMagic());
			if (spell.endsWith(" Bolt") && containsItem(selected, "chaos gauntlets"))
			{
				baseMaxHit += 3;
			}
			int magicDamagePercent = selected.values().stream().mapToInt(GearItem::getStrengthBonus).sum()
				+ elementalWeaponSpellBonus(weapon);
			maxHit = ElementalSpellScaling.maxHit(baseMaxHit, magicDamagePercent, boss.getElementalWeaknessPercent());
			if (!boss.hasNpcMagicLevel())
			{
				hitChance = clamp(ElementalSpellScaling.applyAccuracyRollMultiplier(hitChance,
					boss.getElementalWeaknessPercent() + elementalWeaponSpellBonus(weapon)), 0.05D, 0.98D);
			}
			attackSpeed = elementalAttackSpeed(weapon);
			warnings.add(boss.getElementalWeaknessPercent() + "% " + boss.getElementalWeakness().displayName()
				+ " weakness: cast " + spell + ". The weakness adds " + boss.getElementalWeaknessPercent()
				+ "% to its accuracy roll and base damage; powered staves do not benefit.");
		}
		else if (style == CombatStyle.MAGIC && boss.hasElementalWeakness())
		{
			String spell = ElementalSpellScaling.bestSpellName(boss.getElementalWeakness(), stats.getMagic());
			if (!spell.isEmpty())
			{
				warnings.add(boss.getElementalWeaknessPercent() + "% " + boss.getElementalWeakness().displayName()
					+ " weakness available with " + spell + "; the selected powered/non-standard staff receives no weakness bonus.");
			}
		}
		if (style == CombatStyle.MAGIC && boss.getLabel().toLowerCase(Locale.ROOT).contains("royal titans"))
		{
			warnings.add("Royal Titans use opposite weaknesses: Branda is 50% weak to Water; Eldric is 50% weak to Fire. Twinflame can switch automatically when the required spells and runes are available.");
		}
		double elementalExtraHit = usesElementalWeakness ? elementalExtraHitMultiplier(weapon,
			ElementalSpellScaling.bestSpellName(boss.getElementalWeakness(), stats.getMagic())) : 1.0D;
		double dps = round(((maxHit * hitChance / 2.0D) / attackSpeed) * elementalExtraHit * styleMultiplier(boss, style));
		int loadoutFit = calculateLoadoutFit(boss, style, stats, selected, warnings);

		return new SetupRecommendation(boss.getLabel(), displayStyle(style, boss), selected, slotAlternatives, dps, hitChance, maxHit, loadoutFit, warnings, Collections.emptyList());
	}

	private static double magicHitChance(Map<GearSlot, GearItem> selected, int magicLevel, BossTarget boss,
		int conditionalAccuracyPercent)
	{
		int magicAttackBonus = selected.values().stream().mapToInt(GearItem::getAttackBonus).sum();
		long attackRoll = ElementalSpellScaling.magicAttackRoll(magicLevel, magicAttackBonus, conditionalAccuracyPercent);
		long defenceRoll = ElementalSpellScaling.npcMagicDefenceRoll(boss.getNpcMagicLevel(), boss.getDefMagic());
		return ElementalSpellScaling.hitChance(attackRoll, defenceRoll);
	}

	private static boolean containsItem(Map<GearSlot, GearItem> selected, String itemName)
	{
		return selected.values().stream().anyMatch(item -> item.getName().equalsIgnoreCase(itemName));
	}

	private static int itemScore(GearItem item, BossTarget boss, CombatStyle style, PlayerStats stats)
	{
		int score = item.scoreValue();
		if (style == CombatStyle.MAGIC && item.getSlot() == GearSlot.WEAPON && boss.hasElementalWeakness()
			&& ElementalSpellScaling.canCastElementalSpell(item.getName())
			&& ElementalSpellScaling.bestBaseMaxHit(boss.getElementalWeakness(), stats.getMagic()) > 0)
		{
			score += boss.getElementalWeaknessPercent() * 4 + elementalWeaponSpellBonus(item) * 2;
		}
		return score;
	}

	private static int elementalWeaponSpellBonus(GearItem weapon)
	{
		String name = weapon == null ? "" : weapon.getName().toLowerCase(Locale.ROOT);
		return name.contains("twinflame staff") || name.contains("smoke battlestaff") ? 10 : 0;
	}

	private static double elementalAttackSpeed(GearItem weapon)
	{
		String name = weapon == null ? "" : weapon.getName().toLowerCase(Locale.ROOT);
		if (name.contains("harmonised nightmare staff")) return 2.4D;
		if (name.contains("twinflame staff")) return 3.6D;
		return 3.0D;
	}

	private static double elementalExtraHitMultiplier(GearItem weapon, String spellName)
	{
		String weaponName = weapon == null ? "" : weapon.getName().toLowerCase(Locale.ROOT);
		boolean eligibleTier = spellName.endsWith("Bolt") || spellName.endsWith("Blast") || spellName.endsWith("Wave");
		return weaponName.contains("twinflame staff") && eligibleTier ? 1.4D : 1.0D;
	}

	private static void filterAmmoForWeapon(Map<GearSlot, GearItem> selected, Map<GearSlot, List<GearItem>> slotAlternatives, GearItem weapon)
	{
		List<GearItem> ammoAlternatives = slotAlternatives.get(GearSlot.AMMUNITION);
		if (ammoAlternatives == null || ammoAlternatives.isEmpty())
		{
			return;
		}
		List<GearItem> compatible = ammoAlternatives.stream()
			.filter(weapon::acceptsAmmo)
			.collect(Collectors.toList());
		if (compatible.isEmpty())
		{
			selected.remove(GearSlot.AMMUNITION);
			return;
		}
		selected.put(GearSlot.AMMUNITION, compatible.get(0));
	}

	private static CombatStyle displayStyle(CombatStyle style, BossTarget boss)
	{
		if (style != CombatStyle.MELEE)
		{
			return style;
		}
		int stab = boss.getDefStab();
		int slash = boss.getDefSlash();
		int crush = boss.getDefCrush();
		if (stab <= slash && stab <= crush) return CombatStyle.STAB;
		if (slash <= stab && slash <= crush) return CombatStyle.SLASH;
		return CombatStyle.CRUSH;
	}

	private static void addRequirementWarnings(CombatStyle style, PlayerStats stats, List<String> warnings)
	{
		if (style == CombatStyle.MAGIC && stats.getMagic() < 75)
		{
			warnings.add("Magic level is below 75, so top-tier magic gear is filtered out.");
		}
		if (style == CombatStyle.RANGED && stats.getRanged() < 75)
		{
			warnings.add("Ranged level is below 75, so top-tier ranged gear is filtered out.");
		}
		if (style.isMelee()
			&& (stats.getAttack() < 75 || stats.getStrength() < 75))
		{
			warnings.add("Melee stats are below 75, so top-tier melee gear is filtered out.");
		}
	}

	private static int calculateLoadoutFit(BossTarget boss, CombatStyle style, PlayerStats stats, Map<GearSlot, GearItem> items, List<String> warnings)
	{
		int core = basicLoadoutScore(boss.getTargetCombat(), stats.getHitpoints(), stats.getPrayer(), stats.getDefence(), boss.getTargetCombat(), 43);
		double styleRatio;
		if (style == CombatStyle.MAGIC)
		{
			styleRatio = stats.getMagic() / (double) boss.getTargetMagic();
		}
		else if (style == CombatStyle.RANGED)
		{
			styleRatio = stats.getRanged() / (double) boss.getTargetRanged();
		}
		else
		{
			styleRatio = Math.min(stats.getAttack() / (double) boss.getTargetAttack(), stats.getStrength() / (double) boss.getTargetStrength());
		}
		int gearSlots = items.size();
		int score = (int) Math.round(core * 0.45D + clamp(styleRatio, 0.0D, 1.0D) * 40.0D + Math.min(gearSlots, 10) * 1.5D);
		if (!warnings.isEmpty())
		{
			score -= 5;
		}
		return Math.max(0, Math.min(100, score));
	}

	private static double styleLevel(CombatStyle style, PlayerStats stats)
	{
		switch (style)
		{
			case MAGIC:
				return stats.getMagic();
			case RANGED:
				return stats.getRanged();
			case MELEE:
				return Math.max(1.0D, (stats.getAttack() + stats.getStrength()) / 2.0D);
			default:
				return (stats.getAttack() + stats.getStrength()) / 2.0D;
		}
	}

	private static double styleDamageLevel(CombatStyle style, PlayerStats stats)
	{
		switch (style)
		{
			case MAGIC:
				return stats.getMagic();
			case RANGED:
				return stats.getRanged();
			case MELEE:
				return stats.getStrength();
			default:
				return stats.getStrength();
		}
	}

	private static double targetPressure(BossTarget boss, CombatStyle style)
	{
		int defence;
		switch (style)
		{
			case MAGIC:
				defence = boss.getDefMagic();
				break;
			case RANGED:
				defence = boss.getDefRanged();
				break;
			case MELEE:
				defence = Math.min(boss.getDefStab(), Math.min(boss.getDefSlash(), boss.getDefCrush()));
				break;
			case STAB:
				defence = boss.getDefStab();
				break;
			case SLASH:
				defence = boss.getDefSlash();
				break;
			case CRUSH:
			default:
				defence = boss.getDefCrush();
				break;
		}
		return clamp(defence / 700.0D, 0.0D, 0.45D);
	}

	private static double styleMultiplier(BossTarget boss, CombatStyle style)
	{
		String name = boss.getLabel().toLowerCase();
		if (name.contains("zulrah") && style == CombatStyle.MAGIC)
		{
			return 1.45D;
		}
		if (name.contains("zulrah") && style == CombatStyle.RANGED)
		{
			return 0.85D;
		}
		if (name.contains("vorkath") && style == CombatStyle.RANGED)
		{
			return 1.25D;
		}
		if (boss.getAttributes().contains("melee immune") && style.isMelee())
		{
			return 0.25D;
		}
		return 1.0D;
	}

	private static double clamp(double value, double min, double max)
	{
		return Math.max(min, Math.min(max, value));
	}

	private static int basicLoadoutScore(int combatLevel, int hitpointsLevel, int prayerLevel, int defenceLevel,
		int targetCombatLevel, int targetPrayerLevel)
	{
		double combatScore = ratioScore(combatLevel, Math.max(1, targetCombatLevel)) * 0.55D;
		double hitpointsScore = ratioScore(hitpointsLevel, 99) * 0.20D;
		double prayerScore = ratioScore(prayerLevel, Math.max(1, targetPrayerLevel)) * 0.15D;
		double defenceScore = ratioScore(defenceLevel, 99) * 0.10D;
		return Math.max(0, Math.min(100, (int) Math.round(combatScore + hitpointsScore + prayerScore + defenceScore)));
	}

	private static double ratioScore(int actual, int target)
	{
		return Math.min(1.0D, Math.max(0.0D, actual / (double) target)) * 100.0D;
	}

	private static double round(double value)
	{
		return Math.round(value * 100.0D) / 100.0D;
	}

